    builtin.mode != .Debug and
    std.Target.x86.featureSetHas(builtin.cpu.features, .bmi2) and
    std.Target.x86.featureSetHas(builtin.cpu.features, .adx);

pub fn pointAdd(
    output: *[16]u64,
    left: *const [16]u64,
    right: *const [16]u64,
) void {
    if (comptime !enabled) @compileError("ADX Ed25519 is unavailable");
    vailEd25519ExtendedAdd(output, left, right);
}

pub fn pointDouble(output: *[16]u64, point: *const [12]u64) void {
    if (comptime !enabled) @compileError("ADX Ed25519 is unavailable");
    vailEd25519ExtendedDouble(output, point, 1);
}

pub fn pointDoubleProjective(output: *[16]u64, point: *const [12]u64) void {
    if (comptime !enabled) @compileError("ADX Ed25519 is unavailable");
    vailEd25519ExtendedDouble(output, point, 0);
}

pub fn pointPrecomputedAdd(
    output: *[16]u64,
    point: *const [16]u64,
    cached: *const [12]u64,
) void {
    if (comptime !enabled) @compileError("ADX Ed25519 is unavailable");
    vailEd25519PrecomputedAdd(output, point, cached);
}

